'use strict';
const $=id=>document.getElementById(id),M=DmiMapping,sound=new DmiSound();
let frame=null,devices=[],selected='',cfg=M.defaults(),lease='',sequence=0,busy=false,admin=false,lastAck=false,lastVigilance=false,forceEmergency=false,previousStatus='',lastSend=0,remoteInputsAt=0,canRead=false;
const configKey=()=> 'dmi-joystick-v1:'+(device()?.profileKey||selected);
function say(text){$('message').textContent=text}
function device(){return devices.find(d=>d.id===selected)}
function option(select,value,label){let o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}
function form(){let d=device();for(let id of ['power-axis','brake-axis']){let select=$(id);select.replaceChildren();for(let i=0;i<(d?.axes.length??6);i++){option(select,i,d?.axisNames?.[i]||'轴 '+(i+1));select.lastChild.disabled=d?.available?.[i]===false}}
 for(let id of ['emergency-button','ack-button','vigilance-button','power-button','brake-button']){let select=$(id);select.replaceChildren();option(select,-1,'未分配');for(let i=0;i<(d?.buttons.length||0);i++)option(select,i,d?.buttonNames?.[i]||'按钮 '+(i+1))}
 $('power-button').value=cfg.powerButton??-1;$('brake-button').value=cfg.brakeButton??-1;$('mode').value=cfg.mode;$('power-axis').value=cfg.powerAxis;$('brake-axis').value=cfg.brakeAxis;$('emergency-button').value=cfg.emergencyButton;$('ack-button').value=cfg.ackButton;$('vigilance-button').value=cfg.vigilanceButton??-1;$('protection').checked=cfg.protection;
 for(let kind of ['power','brake']){$(kind+'-invert').checked=cfg[kind].invert;$(kind+'-deadzone').value=Math.round(cfg[kind].deadzone*100)}calibrationText();
}
function calibrationText(){for(let kind of ['power','brake']){let c=cfg[kind];$(kind+'-cal').textContent='最小 '+c.min.toFixed(3)+' · 空挡 '+c.center.toFixed(3)+' · 最大 '+c.max.toFixed(3)}$('brake-axis').disabled=cfg.mode!=='separate';$('power-axis').disabled=cfg.mode==='buttons';$('button-drive').hidden=cfg.mode!=='buttons';$('brake-calibration').hidden=cfg.mode!=='separate'}
function readForm(){cfg.powerButton=Number($('power-button').value);cfg.brakeButton=Number($('brake-button').value);cfg.mode=$('mode').value;cfg.powerAxis=Number($('power-axis').value);cfg.brakeAxis=Number($('brake-axis').value);cfg.emergencyButton=Number($('emergency-button').value);cfg.ackButton=Number($('ack-button').value);cfg.vigilanceButton=Number($('vigilance-button').value);cfg.protection=$('protection').checked;for(let kind of ['power','brake']){cfg[kind].invert=$(kind+'-invert').checked;cfg[kind].deadzone=Number($(kind+'-deadzone').value)/100}calibrationText()}
function load(){cfg=M.defaults();try{let saved=JSON.parse(localStorage.getItem(configKey()));if(saved)cfg={...cfg,...saved,power:{...cfg.power,...saved.power},brake:{...cfg.brake,...saved.brake}}}catch{}form()}
function refreshDevices(next){devices=next;let signature=next.map(d=>d.id).join('|');if($('device').dataset.signature!==signature){$('device').dataset.signature=signature;$('device').replaceChildren();option($('device'),'','请选择摇杆');for(let d of devices)option($('device'),d.id,(!d.id.startsWith('browser:')?'主机 · ':'浏览器 · ')+d.name+(d.backend?' ['+d.backend+']':''));$('device').value=selected}
 if(selected&&!device()&&lease)stop('摇杆已断开，退出接管');
}
function gamepads(){try{return [...(navigator.getGamepads?.()||[])].filter(p=>p?.connected).map(p=>({id:'browser:'+p.index+':'+p.id,name:p.id,axes:[...p.axes],buttons:p.buttons.map(b=>b.pressed)}))}catch{return []}}
async function request(path,body){return CTCS.api.post(path,body,false)}
async function stop(message='已停止接管；游戏保持最后档位'){let old=lease;lease='';forceEmergency=false;if(old)try{await request('/api/mapping/stop',{lease:old})}catch{}say(message);buttons()}
function buttons(){let input;try{input=M.read(device(),cfg)}catch{}let enabled=!!lease;
 $('start').disabled=enabled||busy||!admin||!input||input.emergency||input.throttle>1||input.brake>1||!frame?.Fresh||!frame?.Brake?.ready||frame?.Ato?.active||frame.GameAdvancing===false||(cfg.protection&&!Number.isFinite(frame.Supervision?.permitted));$('stop').disabled=!enabled;$('ack').disabled=!enabled||busy;$('emergency').disabled=!enabled;$('device').disabled=enabled;$('mode').disabled=enabled;$('calibration').disabled=enabled;
}
$('device').onchange=()=>{selected=$('device').value;load();say('设备已选择。校准只预览，不会发送游戏指令。')};
for(let id of ['mode','power-axis','brake-axis','power-invert','brake-invert','power-deadzone','brake-deadzone','emergency-button','ack-button','vigilance-button','power-button','brake-button','protection'])$(id).onchange=()=>{if(!lease)readForm()};
for(let button of document.querySelectorAll('[data-cal]'))button.onclick=()=>{let [kind,point]=button.dataset.cal.split(':'),raw=device()?.axes[cfg[kind==='power'?'powerAxis':'brakeAxis']];if(!Number.isFinite(raw))return say('所选轴不可用');cfg[kind][point]=raw;calibrationText();say('已记录 '+raw.toFixed(3)+'。移动到另一端或空挡继续校准。')};
$('save').onclick=()=>{try{readForm();M.read(device(),cfg);localStorage.setItem(configKey(),JSON.stringify(cfg));say('已保存此设备校准，下次选择此设备自动加载。')}catch(e){say(e.message)}};
$('reset').onclick=()=>{cfg=M.defaults();form();say('已恢复默认校准，请检查预览方向。')};
$('start').onclick=async()=>{if(busy)return;busy=true;buttons();try{await sound.unlock();readForm();let input=M.read(device(),cfg);if(input.emergency)throw Error('请松开紧急制动按钮');let r=await request('/api/mapping/start',{vehicle:frame.Vehicle,device:selected,protection:cfg.protection,config:cfg,...input});lease=r.lease;sequence=0;lastAck=input.ack;lastVigilance=input.vigilance;lastSend=0;localStorage.setItem(configKey(),JSON.stringify(cfg));say(r.message)}catch(e){say(e.message)}finally{busy=false;buttons()}};
$('stop').onclick=()=>stop();
async function ack(){if(!lease||busy)return;busy=true;try{let r=await request('/api/mapping/ack',{lease});say(r.message);sound.play('S_click')}catch(e){say(e.message)}finally{busy=false}}
$('ack').onclick=ack;$('emergency').onclick=async()=>{if(selected.startsWith('browser:')){forceEmergency=true;say('紧急制动请求待发送')}else try{await CTCS.api.post('/api/brake',{vehicle:frame.Vehicle,percent:100,emergency:true});lease='';say('紧急制动已发送，摇杆接管已停止')}catch(e){say(e.message)}};
function feedback(){if(!frame)return;let n=v=>Number.isFinite(v)?v.toFixed(1):'—',s=frame.Supervision||{},m=frame.Mapping||{};
 $('game-status').textContent=!frame.Fresh?'等待 TSW 连接':!frame.DmiReady?(frame.CabActivation?.reason||'等待司机室激活'):frame.GameAdvancing===false?'游戏时间未推进':'TSW 实时连接';$('vehicle').textContent=(frame.Vehicle||'车辆未知')+' · '+(frame.Brake?.supported?'真实操纵映射可用':'此车型仅可校准预览');$('feedback').textContent='速度 '+n(frame.Speed)+' km/h · 加速度 '+n(frame.Acceleration)+' m/s² · 实际手柄 '+n(frame.Brake?.input)+' · 实际档位 '+n(frame.Brake?.output);
 $('protection-status').textContent=(s.system||'AUTO')+' · '+(s.source||'等待有效限速')+'\n允许 '+n(s.permitted)+' km/h · '+(s.reason||'')+'\n'+(m.message||'未启用映射');$('station').textContent=M.station(frame);$('stations').replaceChildren();for(let station of (frame.Stations||[]).slice(1,5)){let row=document.createElement('div');row.textContent=station.name+' · '+M.distance(station.distance)+(station.platform?' · '+station.platform+' 站台':'');$('stations').append(row)}
 $('events').replaceChildren();for(let event of (m.events||[]).slice(0,8)){let row=document.createElement('div');row.textContent=event.time+'  '+event.text;$('events').append(row)}if(!m.events?.length)$('events').textContent='尚无事件';
 $('operation-state').textContent=(frame.Operations?.message||'等待司机室激活')+' · '+(frame.Operations?.elapsed||0)+' s / '+(frame.Operations?.distance||0)+' m';let status=m.emergencyLatched?'EB':m.serviceLatched?'SB':s.status;if(lease&&status!==previousStatus&&['EB','SB','warning'].includes(status))sound.play(status==='warning'?'S1_toofast':'S2_warning');previousStatus=status;
 if(lease&&!m.armed)stop(m.message||'接管已结束');
}
async function tick(){let received=false;try{
 let [f,native]=await Promise.all([CTCS.api.get('/api/frame'),canRead?CTCS.api.get('/api/joysticks'):Promise.resolve({devices:[]})]);received=true;admin=CTCS.api.canManageConnection;canRead=admin;frame=f;$('device-status').textContent=(native.devices?.length||0)+' 个主机输入通道 · '+gamepads().length+' 个浏览器通道'+(native.message?' · '+native.message:'');remoteInputsAt=performance.now();refreshDevices([...(native.devices||[]),...gamepads()]);feedback();
 let input=null;try{input=M.read(device(),cfg);$('raw').textContent=device().axes.map((v,i)=>'轴 '+(i+1)+' '+v.toFixed(3)).join('　')+'\n按下按钮：'+device().buttons.map((v,i)=>v?i+1:null).filter(Boolean).join(', ');for(let [kind,key]of [['power','throttle'],['brake','brake']]){$(kind+'-value').textContent=Math.round(input[key])+'%';$(kind+'-meter').value=input[key]}}catch(e){$('raw').textContent=e.message;if(lease)await stop(e.message)}
 if(lease&&input&&!busy&&selected.startsWith('browser:')){if(input.vigilance&&!lastVigilance){await CTCS.api.operation({action:'vigilance',vehicle:frame.Vehicle})}else if(input.ack&&!lastAck){await ack()}else if(performance.now()-lastSend>=240){busy=true;lastSend=performance.now();try{let r=await request('/api/mapping/input',{lease,sequence:++sequence,device:selected,...input,emergency:input.emergency||forceEmergency});forceEmergency=false;frame.Mapping=r.mapping;say(r.mapping.message)}catch(e){await stop(e.message)}finally{busy=false}}lastAck=input.ack;lastVigilance=input.vigilance}
 }catch(e){if(!received)frame=null;$('game-status').textContent=received?'页面显示异常（桥接已连接）':'桥接连接已断开，正在重试';if(lease)await stop(received?'页面异常，映射已停止':'桥接断开，映射已停止');say(e.message)}finally{buttons();setTimeout(tick,250)}}
window.addEventListener('pagehide',()=>{if(lease){fetch('/api/mapping/stop',{method:'POST',headers:{'Content-Type':'application/json','X-DMI-Token':CTCS.api.token},body:JSON.stringify({lease}),keepalive:true}).catch(()=>{});lease=''}});
// Browser input is only valid while that controller page is visible. Native host polling can continue in another window.
document.addEventListener('visibilitychange',()=>{if(document.hidden&&lease&&selected.startsWith('browser:'))stop('手柄页面已隐藏，退出接管')});
async function boot(){form();try{let b=await CTCS.api.init();admin=b.canManageConnection;canRead=admin;if(!admin)say('请在 TSW 主机打开 http://127.0.0.1:31271/joystick.html 配置摇杆')}catch(e){say(e.message)}tick()}boot();

for(let [id,action]of [['vigilance-op','vigilance'],['release-op','release'],['braketest-op','braketest']])$(id).onclick=async()=>{try{let r=await CTCS.api.operation({action,vehicle:frame?.Vehicle});$('operation-result').textContent=r.message}catch(e){$('operation-result').textContent=e.message}};

$('load-levers').onclick=async()=>{try{let r=await CTCS.api.get('/api/levers');$('vehicle-lever').replaceChildren();for(let control of r.controls)option($('vehicle-lever'),control,control.split('/').pop());$('calibration-result').textContent='当前车型：'+(frame?.Vehicle||'未知')+'。请选择真实组合手柄，停车后记录四个位置。'}catch(e){$('calibration-result').textContent=e.message}};
for(let button of document.querySelectorAll('[data-capture]'))button.onclick=async()=>{try{let r=await CTCS.api.post('/api/vehicle-map',{vehicle:frame?.Vehicle,control:$('vehicle-lever').value,point:button.dataset.capture});$('calibration-result').textContent=r.message+(r.points?'\n'+Object.entries(r.points).map(([key,p])=>({neutral:'空挡',power:'最大牵引',service:'常用制动',emergency:'紧急制动'})[key]+'：输入 '+p.input.toFixed(4)+' / 输出 '+p.output).join('\n'):'')}catch(e){$('calibration-result').textContent=e.message}};
